const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '!vendor' -g '!web' -g '!node_modules'","workdir":"/app","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"rg -n 'db ls|database.*ls|ListDatabase|GetDatabaseServers|DatabaseServers' tool tsh lib/client api | head -n 240","workdir":"/app","yield_time_ms":10000,"max_output_tokens":8000}),
  tools.exec_command({cmd:"git status --short","workdir":"/app","yield_time_ms":10000,"max_output_tokens":1000})
]); results.forEach((r,i)=>text(JSON.stringify({i,result:r}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '!vendor' -g '!web' -g '!node_modules'","workdir":"/app","yield_time_ms":10000,"max_output_tokens":2000}),
