  tools.exec_command({cmd:"git status --short","workdir":"/app","yield_time_ms":10000,"max_output_tokens":1000})
]); results.forEach((r,i)=>text(JSON.stringify({i,result:r})));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -not -path './vendor/*' -print","workdir":"/app","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"grep -R -n -E 'db ls|ListDatabase|GetDatabaseServers|DatabaseServers' tool tsh lib/client api --exclude-dir=vendor 2>/dev/null | head -n 240","workdir":"/app","yield_time_ms":10000,"max_output_tokens":8000}),
  tools.exec_command({cmd:"find .codex-role-output -maxdepth 2 -type f -print 2>/dev/null","workdir":"/app","yield_time_ms":10000,"max_output_tokens":1000})
]); results.forEach((r,i)=>text(JSON.stringify({i,result:r})));

